<div class="page-header"><div><div class="eyebrow">FINANCE / ACCOUNTING</div><h1>Journal Entries</h1><p>Posted and draft accounting transactions generated by TMS.</p></div></div>
<div class="card finance-table-card"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Entry</th><th>Journal</th><th>Reference</th><th>Status</th><th>Debit</th><th>Credit</th></tr></thead><tbody><?php if(empty($entries)): ?><tr><td colspan="7" class="empty-cell">No journal entries yet.</td></tr><?php endif ?><?php foreach($entries as $e): ?><tr><td><?= esc($e['entry_date']) ?></td><td><strong><?= esc($e['entry_no']) ?></strong><small><?= esc($e['description'] ?: '') ?></small></td><td><?= esc(($e['journal_code'] ?? '').' - '.($e['journal_name'] ?? '')) ?></td><td><?= esc(($e['reference_type'] ?? '').' #'.($e['reference_id'] ?? '')) ?></td><td><span class="badge <?= $e['status']==='posted'?'badge-success':'badge-warning' ?>"><?= esc(ucfirst($e['status'])) ?></span></td><td class="money">Rp <?= number_format((float)($e['total_debit'] ?? 0),0,',','.') ?></td><td class="money">Rp <?= number_format((float)($e['total_credit'] ?? 0),0,',','.') ?></td></tr><?php endforeach ?></tbody></table></div></div>
